#!/bin/bash
# DEPLOY_v2_accept — اختبار القبول النهائي. جولة واحدة، حكم واحد، بلا إصلاح بعدها.
# لا تفعيل إنتاج هنا: علم LEGALMIND_RETRIEVAL_V2 لا يُضبط، وapp.py لا يُمَس.
set -u
cd /opt/LegalMind || exit 1
cat > /tmp/acc.b64 <<'B64EOF'

B64EOF
base64 -d /tmp/acc.b64 > /tmp/acc.tgz || { echo "B64_FAIL"; exit 1; }
tar xzf /tmp/acc.tgz -C /opt/LegalMind || { echo "UNTAR_FAIL"; exit 1; }
set -a; . /opt/LegalMind/deploy/.env; set +a
nohup /opt/LegalMind/admin/.venv/bin/python \
      /opt/LegalMind/tools/v2_close.py > /tmp/v2accept.log 2>&1 &
disown
echo "بدأ اختبار القبول. تابع:  tail -f /tmp/v2accept.log"
echo "السطر قبل الأخير يحمل الحكم: RETRIEVAL_V2_READY أو RETRIEVAL_V2_FAILED"
